} from "@/lib/auth-hint";

const AUTH_DISPLAY_ATTRIBUTE = "data-eve-auth-display";

const authDisplayScript = `
(() => {
  try {
    const loggedIn = document.cookie
      .split("; ")
      .some((cookie) => cookie === ${JSON.stringify(
